CATALOG_QUERIES = {'constraints': "SELECT n.nspname,r.relname,k.conname,k.contype,k.condeferrable,k.condeferred,k.convalidated,k.confupdtype,k.confdeltype,k.confmatchtype,coalesce(pn.nspname,''),coalesce(p.relname,''),k.conkey,k.confkey,pg_get_constraintdef(k.oid,true) FROM pg_constraint k JOIN pg_class r ON r.oid=k.conrelid JOIN pg_namespace n ON n.oid=r.relnamespace LEFT JOIN pg_class p ON p.oid=k.confrelid LEFT JOIN pg_namespace pn ON pn.oid=p.relnamespace WHERE n.nspname='public' ORDER BY r.relname,k.conname", 'indexes': "SELECT t.relname,i.relname,x.indisunique,x.indisprimary,x.indisvalid,x.indisready,x.indislive,pg_get_indexdef(i.oid) FROM pg_index x JOIN pg_class t ON t.oid=x.indrelid JOIN pg_class i ON i.oid=x.indexrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' ORDER BY t.relname,i.relname", 'enums': "SELECT t.typname,e.enumlabel,e.enumsortorder FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace JOIN pg_enum e ON e.enumtypid=t.oid WHERE n.nspname='public' ORDER BY t.typname,e.enumsortorder", 'trigger_catalog': "SELECT r.relname,t.tgname,t.tgtype,t.tgenabled,t.tgisinternal,t.tgdeferrable,t.tginitdeferred,t.tgnargs,t.tgattr::text,pg_get_expr(t.tgqual,t.tgrelid),pn.nspname,p.proname,pg_get_triggerdef(t.oid,true) FROM pg_trigger t JOIN pg_class r ON r.oid=t.tgrelid JOIN pg_namespace n ON n.oid=r.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace WHERE n.nspname='public' AND NOT t.tgisinternal ORDER BY r.relname,t.tgname"}

def inventory():
    """Return a fresh decoded copy; callers cannot mutate the frozen profile."""
    return json.loads(PROFILE_JSON)

def check_sources(root=None):
    root = Path(root) if root is not None else Path(__file__).resolve().parents[2]
    expected=inventory()
    actual={p.relative_to(root).as_posix() for p in (root/'core/migrations').glob('*.sql')}
    actual.update(p.relative_to(root).as_posix() for p in (root/'modules').glob('*/migrations/*.sql'))
    if actual != set(expected['sql_sources']):
        raise MigrationError('Positive027 SQL path inventory differs')
    for name,digest in expected['sources'].items():
        try:actual_digest=hashlib.sha256((root/name).read_bytes()).hexdigest()
        except OSError:raise MigrationError('Positive027 source is missing') from None
        if actual_digest != digest:raise MigrationError('Positive027 source integrity differs')

def validate_snapshot(snapshot):
    """Exact catalogue comparison; no subtraction, repair, or adoption."""
    expected=inventory()
    keys=('profile','dialect','schema','raw_tables','raw_columns','ledger','functions','triggers',*CATALOG_QUERIES)
    if type(snapshot) is not dict or any(key not in snapshot or snapshot[key] != expected[key] for key in keys):
        raise MigrationError('Positive027 retained catalogue differs')

def validate_connection(connection):
    """Readonly exact PG catalogue oracle; no stage/restore authority minted."""
    check_sources()
    if connection.dialect.name != 'postgresql':raise MigrationError('Positive027 PostgreSQL catalogue required')
    from core.schema.bootstrap import schema_manifest
    expected=inventory()
    snapshot={'profile':'pre-priced-027','dialect':'postgresql','schema':schema_manifest(connection),
              'raw_tables':expected['raw_tables'],'raw_columns':expected['raw_columns'],
              'ledger':[list(row) for row in connection.execute(text('SELECT migration_id,checksum,dialect FROM odin_schema_migrations ORDER BY migration_id'))],
              'functions':expected['functions'],'triggers':expected['triggers']}
    # Catalogue trigger rows include actual linked function names/OIDs through
    # joins; source canonical executable validator checks all actual attributes.
    from modules.system.postgres_canonical_executables import validate_executables
    validate_executables(connection)
    for name,query in CATALOG_QUERIES.items():snapshot[name]=[list(row) for row in connection.execute(text(query))]
    validate_snapshot(snapshot)
